insert into public.site_content (key, value) values ('studio', '{"name":"Studio In & Out","tagline":"Architecture | Interior | Space Planning","whatsapp":"917506147251","instagram":"https://www.instagram.com/studio.inandout/","instagram_handle":"@studio.inandout","email":"studioinandoutk@gmail.com","phones":[{"name":"Ar. Sakina Kachwala","number":"+91 98338 77752"},{"name":"Abdeali Kachwala","number":"+91 75061 47251"}],"address_lines":["363, Bhagubai Chambers,","Narsi Natha Street,","Office No. 18, 2nd Floor,","Masjid Bundar (W), Mumbai 400009"]}'::jsonb)
insert into public.site_content (key, value) values ('hero', '{"headline_before":"A perspective","headline_em":"beyond","headline_after":"aesthetics.","in":{"word":"IN","label":"Interior","image":"/assets/r1_living.jpg","alt":"Living room with a curved leather sofa and navy panelling, Piramal 603"},"out":{"word":"OUT","label":"Architecture","image":"/assets/balc_big.jpg","alt":"A balcony looking out over the Mumbai skyline"}}'::jsonb)
insert into public.site_content (key, value) values ('statement', '{"text":"We don''t simply design spaces. We shape experiences, evoke emotions, and create environments that leave a lasting impression.","note":"At Studio In & Out, every detail has intention, every element has purpose, and every space tells a story.","stat_value":"60,000+","stat_unit":"sq. ft.","stat_caption":"designed & delivered","image_arch":"/assets/ar_g.jpg","image_small":"/assets/st_e.jpg"}'::jsonb)
insert into public.site_content (key, value) values ('philosophy', '{"title_before":"Our philosophy is","title_em":"simple.","intro":"Three ideas guide every project we take on, from the first sketch to the last cushion.","ideas":[{"lead_in":"Design with","word":"purpose.","text":"Every space starts with how you will live in it, so each line on the drawing has a reason to be there.","image":"/assets/st_c.jpg","alt":"A calm TV wall with a stone-textured panel and floating console"},{"lead_in":"Create with","word":"character.","text":"Materials, colour and craft chosen to make a home feel unmistakably yours.","image":"/assets/s_bar.jpg","alt":"A breakfast bar with red fluted detailing and brass accents"},{"lead_in":"Inspire through","word":"every detail.","text":"From the joinery to the light fittings, the small things are what you notice every day.","image":"/assets/r1_chand.jpg","alt":"A green glass chandelier above a dining table"}]}'::jsonb)
insert into public.site_content (key, value) values ('services', '{"title":"What we do","intro":"Two perspectives under one roof, so the building and the rooms inside it are designed as one.","cards":[{"tag":"In","title":"Interior design","text":"Homes and workplaces: planning, joinery, materials, lighting and styling.","image":"/assets/ar_a.jpg","alt":"Bedroom with a fan-pleated headboard and brass sconces"},{"tag":"&","title":"Space planning","text":"Layouts that make every square foot work, planned and checked before anything is built.","image":"/assets/st_b.jpg","alt":"Bedroom with a terracotta sculpted panel"},{"tag":"Out","title":"Architecture","text":"New buildings, renovations and façades, planned around site and purpose.","image":"/assets/hero2.jpg","alt":"Bedroom window looking out over the Mumbai skyline"}]}'::jsonb)
insert into public.site_content (key, value) values ('founders', '{"names":"Abdeali Kachwala & Ar. Sakina Kachwala","paragraphs":["United by a shared passion for design, Abdeali and Sakina bring together two distinct perspectives, interior design and architecture, to create spaces that are both expressive and purposeful.","As the co-founders of Studio In & Out, their approach goes beyond aesthetics, focusing on thoughtful spatial planning, refined detailing, and a deep understanding of how people experience spaces.","Abdeali brings a keen eye for materials, detailing, and design expression, while Sakina lends her architectural perspective, balancing creativity with spatial clarity and functionality.","Together, they believe that exceptional design is not defined by extravagance, but by intention, individuality, and the seamless harmony of form and function."],"quote":"Two perspectives. One vision. A distinctive approach to design.","photo":"/assets/founders.jpg","photo_alt":"Ar. Sakina Kachwala and Abdeali Kachwala seated together in one of their interiors","people":[{"name":"Ar. Sakina Kachwala","role":"Principal Architect"},{"name":"Abdeali Kachwala","role":"Principal Designer"}]}'::jsonb)
insert into public.site_content (key, value) values ('contact', '{"title":"Start a project","lead":"Tell us about your space and we will get back to you.","project_types":["Home interiors","Architecture / new build","Workspace or commercial","Space planning"]}'::jsonb)
insert into public.site_content (key, value) values ('join', '{"title":"Join Us","lead":"We are always looking for reliable contractors and craftspeople across Mumbai. If you do good work and finish on time, send us your details.","trades":["Civil & masonry","Carpentry & joinery","Electrical","Plumbing","False ceiling & POP","Painting & polishing","Tiling & stone","Fabrication","Glass & aluminium","Upholstery & furnishing"],"steps":[{"title":"Send your details","text":"Your trade and a few photos of past work."},{"title":"We call you","text":"The studio reviews your work and calls to discuss."},{"title":"Meet on site","text":"We meet at a running site before the first project together."}]}'::jsonb)
insert into public.site_content (key, value) values ('projects_page', '{"intro":"Recent homes by Studio In & Out, each with its story and photographs, followed by short walkthrough films."}'::jsonb)
insert into public.site_content (key, value) values ('walkthroughs', '[{"project_slug":"arav","title":"Piramal Arav 4706","badge":"Living room","text":"Soft neutrals, a cushioned TV wall and light through sheer curtains.","video":"/assets/reel_arav.mp4","poster":"/assets/reel_arav_p.jpg","alt":"Walkthrough of the Piramal Arav 4706 living room"},{"project_slug":"sterling","title":"Sterling 1003","badge":"Entrance and living","text":"Arched cabinetry, walnut joinery and a patterned entrance passage.","video":"/assets/reel_sterling.mp4","poster":"/assets/reel_sterling_p.jpg","alt":"Walkthrough of the Sterling 1003 entrance and living room"}]'::jsonb)
insert into public.projects (slug, number, kind, name, facts, concept_note, documents, sort_order, published) values ('a3805', '01', 'Studio extension', 'Studio A3805', '[{"label":"Area","value":"350 sq. ft."},{"label":"Scope","value":"Interior design"},{"label":"Key idea","value":"A rotating TV unit that works as a partition"}]'::jsonb, array['Studio A3805 represents the art of maximization within a compact footprint. Designed as a 350 sq. ft. extension across the passage from the client''s existing 3BHK, this project was conceived with a singular vision: to establish a distinct, formal living sanctuary that balances modern entertainment with traditional hospitality.', 'The layout is centered around a dynamic architectural intervention: a custom-designed, rotating TV unit. This pivotal element functions as a flexible partition, effectively zoning the studio into two distinct moods while maintaining an open, airy feel.', 'On one side lies the contemporary social zone, featuring a plush sofa setup and a bespoke breakfast counter/juice bar. The bar becomes a visual focal point with its vibrant red fluted detailing and brass accents, complemented by the softness of floral printed mirrors that add depth and intrigue.', 'On the other side of the rotating divider, the design pays homage to cultural roots with a traditional Indian Baithak. This zone is dedicated to relaxed, low-seating comfort, framed by elegant wall moldings and warm, ambient lighting. The material palette throughout creates a cohesive sense of luxury, utilizing rich designer veneers, coffered ceilings, and curated decor to transform a small extension into a grand statement of style.']::text[], '[]'::jsonb, 1, true)
