insert into public.projects (slug, number, kind, name, facts, concept_note, documents, sort_order, published) values ('a3804', '02', 'Residence', 'Studio A3804', '[{"label":"Type","value":"Residence"},{"label":"Scope","value":"Interior design"},{"label":"Palette","value":"Neutrals, wood, blue and blush"}]'::jsonb, array['Studio A3804 is a thoughtfully curated residential interior that celebrates understated elegance through balance, comfort, and continuity. Designed as a seamless extension of the client''s lifestyle, the project brings together refined aesthetics and everyday functionality, creating spaces that feel warm, personal, and timeless.', 'The home is envisioned with a soft modern sensibility, where muted colour palettes, tactile materials, and gentle contrasts define each space. From the dining area to the living and bedrooms, the design language remains cohesive, anchored by neutral backdrops, enriched with natural wood finishes, fluted details, and subtle accents in blues, blush tones, and earthy hues.', 'The dining space acts as a quiet focal point, combining clean-lined furniture with curated lighting and textured wall treatments to elevate daily rituals. Custom cabinetry and display units enhance storage while maintaining visual lightness. The living area is designed as a comfortable yet elegant retreat, layered with plush seating, soft furnishings, and controlled natural light to create a welcoming atmosphere for both family gatherings and intimate moments.', 'Private spaces are treated with a calmer, more intimate approach. The bedrooms are conceived as restful sanctuaries, defined by upholstered headboards, soft textiles, and carefully selected accent elements that add warmth without overpowering the space. Decorative lighting, minimal open shelving, and curated décor introduce character while preserving a sense of visual calm.', 'Throughout Studio A3804, attention is given to proportion, material harmony, and detailing, ensuring that every element contributes to a unified narrative. The result is a home that feels refined yet lived-in, where modern design meets comfort, and aesthetics quietly support the rhythm of everyday life.']::text[], '[]'::jsonb, 2, true)
