insert into public.projects (slug, number, kind, name, facts, concept_note, documents, sort_order, published) values ('lonavala-abode', '06', 'Architecture', 'Lonavala Abode', '[{"label":"Type","value":"6-BHK luxury villa"},{"label":"Scope","value":"Architecture"},{"label":"Location","value":"Lonavala"},{"label":"Status","value":"Under construction"}]'::jsonb, array['This 6-BHK luxury villa is an architectural response to the need for a “home away from home”, a space that functions as a private ecosystem. The design departs from traditional outward-facing luxury, instead adopting an inward-looking morphology that shields the inhabitant from external distractions, creating a profound sense of “seclusion within.”', '## The built vs. the void', 'The project balances high-end minimalist interiors with intentional architectural porosity. By minimizing the interior footprint and maximizing the area dedicated to deep-set balconies and verdant courtyards, the villa dissolves the traditional wall. The result is a living experience where the user is constantly connected to the elements, yet entirely protected from the public gaze.', '## Experiential anchors', 'The site is anchored by two distinct gazebos, strategically placed to offer contrasting environmental moods. One serves as a vibrant, light-filled space for social engagement, while the other is a shaded, quiet retreat for contemplation. These structures ensure that the landscape is not just a view, but a curated sequence of sensory experiences.']::text[], '[{"label":"Download the project panel (PDF)","href":"/assets/lonavala-abode-panel.pdf"}]'::jsonb, 6, true)
